import { Component, computed, inject, resource } from '@angular/core';
import { ActivatedRoute, RouterLink } from '@angular/router';
import { firstValueFrom } from 'rxjs';
import { Solicitud } from '../../../shared/models/solicitud.model';
import { SolicitudService } from '../../../shared/services/solicitud.service';
import { NavigationHistoryService } from '../../../services/navigation-history.service';
import { ResolucionPanelComponent } from '../../../shared/components/resolucion-panel/resolucion-panel.component';

@Component({
  selector: 'app-resolucion-solicitud',
  imports: [RouterLink, ResolucionPanelComponent],
  templateUrl: './resolucion.component.html',
})
export class ResolucionSolicitudComponent {
  private route = inject(ActivatedRoute);
  private solicitudService = inject(SolicitudService);
  private navHistory = inject(NavigationHistoryService);

  readonly folio = this.route.snapshot.paramMap.get('id') ?? '—';
  readonly backRoute = computed(() => this.navHistory.getBackRoute('ejecutivo', 'bandeja/recibidas'));
  readonly solicitudResource = resource({
    params: () => ({ folio: this.folio }),
    loader: ({ params }) => firstValueFrom(this.solicitudService.getByFolio(params.folio)),
  });

  readonly solicitud = computed<Solicitud | null>(() => {
    return (this.solicitudResource.status() as string) === 'resolved' ? (this.solicitudResource.value() ?? null) : null;
  });
  readonly isLoading = computed(() => this.solicitudResource.isLoading());
  readonly hasError = computed(() => {
    return this.solicitudResource.hasValue() && !this.solicitudResource.value() || !!this.solicitudResource.error();
  });

  alStatusCambiado(): void {
    this.solicitudResource.reload();
  }
}
